SELECT `School Name` AS SchoolName, Website 
FROM frpm
WHERE `Free Meal Count (Ages 5-17)` BETWEEN 1900 AND 2000;

SELECT AVG(`Percent (%) Eligible Free (Ages 5-17)`) AS free_rate
FROM frpm
WHERE LOWER(`School Name`) LIKE '%kacey gibson%';

SELECT CAST(SUM(CASE WHEN StatusType = 'Merged' AND DOC = 54 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN StatusType = 'Merged' AND DOC = 52 THEN 1 ELSE 0 END) AS ratio
FROM schools
WHERE County = 'Orange';

SELECT s.School, s.MailZip
FROM schools s
WHERE LOWER(s.AdmFName1) = 'avetik' AND LOWER(s.AdmLName1) = 'atoian';

SELECT s.School AS SchoolName, s.City, s.AdmFName1 || ' ' || s.AdmLName1 AS Admin1_FullName, s.AdmFName2 || ' ' || s.AdmLName2 AS Admin2_FullName, s.AdmFName3 || ' ' || s.AdmLName3 AS Admin3_FullName
FROM schools s
WHERE s.Charter = 1 AND s.CharterNum = '00D2';

SELECT `School Name` AS SchoolName, Latitude, `School Type` AS SchoolType
FROM frpm
WHERE Latitude = (SELECT MAX(Latitude) FROM schools);

SELECT CAST(SUM(CASE WHEN LOWER(gender) = 'f' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS female_proportion
FROM client
WHERE district_id IN (SELECT district_id FROM district WHERE A3 LIKE '%prague%');

SELECT 
  (SELECT COUNT(DISTINCT a.atom_id) FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE LOWER(a.element) = 'i' AND LOWER(b.bond_type) = '-') AS iodine_count,
  (SELECT COUNT(DISTINCT a.atom_id) FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE LOWER(a.element) = 's' AND LOWER(b.bond_type) = '-') AS sulfur_count;

SELECT c.atom_id2 AS bonded_atom_id, a.element AS bonded_element
FROM connected c
JOIN atom a ON c.atom_id2 = a.atom_id
WHERE LOWER(c.atom_id) IN (
    SELECT atom_id FROM atom WHERE LOWER(element) = 'pb'
);

SELECT SUM(CASE WHEN LOWER(label) = '+' THEN 1 ELSE 0 END) AS total_carcinogenic_molecules
FROM molecule
WHERE molecule_id >= 'TR000' AND molecule_id <= 'TR030';

SELECT DISTINCT b.molecule_id 
FROM bond b 
